import {Cursor} from './primitives.js';
import type {MysqlColumn,QueryResult} from '../../../core/contracts.js';
export function errorPacket(buf:Buffer):{code:number;state:string;message:string}{const c=new Cursor(buf);c.byte();const code=c.two();let state='HY000';if(c.remaining()>=6&&c.b[c.p]===35){c.byte();state=c.take(5).toString();}return {code,state,message:c.take(c.remaining()).toString('utf8')};}
export function field(buf:Buffer):MysqlColumn{const c=new Cursor(buf);c.lstr();const schema=c.lstr(),table=c.lstr();c.lstr();const name=c.lstr();c.lstr();const fixed=c.len();if(fixed===null||fixed<12)throw Error('Invalid metadata');const charset=c.two(),length=c.four(),type=c.byte(),flags=c.two(),decimals=c.byte();c.take(2);if(name===null)throw Error('Missing MySQL column name');return {name,schema,table,charset,length,type,flags,decimals,unsigned:!!(flags&32)};}
export function ok(buf:Buffer):QueryResult{const c=new Cursor(buf);if(c.byte()!==0)throw Error('Not an OK packet');const affectedRows=c.len(),insertId=c.len(),status=c.remaining()>=2?c.two():0,warnings=c.remaining()>=2?c.two():0;if(affectedRows===null||insertId===null)throw Error('Invalid OK counts');return {rows:[],columns:[],affectedRows,insertId,status,warnings};}
